            background: "#1c2027", border: "1px solid #3c424d", borderTopColor: "#4b5563",
            borderBottomColor: "#12151a", fontFamily: "monospace",
            textTransform: "uppercase", letterSpacing: "0.06em", color: "#c9d1d9",
