      // Two-step confirm: a single click must not silently drop the primary endpoint.
      var clearS = React.useState(false); var clearArmed = clearS[0], setClearArmed = clearS[1];
      // The host's own view of this endpoint. endpoint_registry answers `primary` with
      // id:"primary" + enabled/batch_allowed/paused + the cached health answer on a current
      // host; an older host answers {url,route} and NOTHING more, so the panel offers no
      // verb the host does not have.
      var p = (props.primary && typeof props.primary === "object" && !Array.isArray(props.primary)) ? props.primary : null;
      var manageable = !!(p && p.id === "primary");
      var unset = !!(manageable && (p.unset === true || p.url === ""));
      var cat = (props.models && Array.isArray(props.models[fn])) ? props.models[fn] : [];
      var names = [];
      for (var i = 0; i < cat.length; i++) if (cat[i] && cat[i].id) names.push(String(cat[i].id));
      // On a host that reports the PRIMARY's own cached capability answer (the primary
      // view now carries models / models_source / models_at exactly like a registry entry),
      // the row shows THAT answer and its age. The panel's dropdown is no longer the row's
      // source of truth — before this change it was, which is why a primary whose engine
      // had never been asked still displayed a confident count borrowed from get_models.
      // On an older host whose primary view carries no models keys, the panel keeps doing
      // what it always did: borrow the dropdown catalog and label it honestly as "get_models"
      // with no age. It never invents an answer the host did not give it.
      var hostAnswer = (manageable && Array.isArray(p.models));
      var epModels = hostAnswer ? p.models : names;
      var epModelsSource = hostAnswer ? (p.models_source || "") : "get_models";
      var epModelsAt = hostAnswer ? (Number(p.models_at) || 0) : 0;
      var st = (props.status && props.status[fn]) ? props.status[fn] : { ok: false };
      var loaded = st.loaded_model ? String(st.loaded_model) : "";
      var loadedQuant = "";
      for (var q = 0; q < cat.length; q++) {
        if (cat[q] && cat[q].id === st.loaded_model && cat[q].quant) { loadedQuant = String(cat[q].quant); break; }
      }
