        fn: fn, index: -1, slot: epSlot(fn, -1), rowCls: "audio-play-endpoint",
        lanePeers: props.lanePeers,   // the same peer list the registered rows count against, so the Primary row and a registered row see one lane
        unset: unset, manageable: manageable, hasFlags: manageable, canEdit: true,
        canClear: manageable, canRemove: false, armed: clearArmed,
        // This row IS the primary slot, so it gets no `set as primary` — the host has
        // no verb that promotes the primary to itself, and its label slot says Primary.
        isPrimary: true, canSetPrimary: false,
        ctlCls: "audio-play-ep-ctl",
        // This row's own occupancy entry (queues[fn].endpoints), passed through.
        occupancy: props.occupancy,
        expanded: !!props.expanded, urlDraft: url, routeDraft: route,
        onUrlDraft: function (v) { setUrl(v); },
        onRouteDraft: function (v) { setRoute(v === "tasks" ? "tasks" : "speech"); },
        onSave: function (f, u, r) { if (props.onSave) props.onSave(f, u, r); },
        onToggleEdit: function (f) { if (props.onExpand) props.onExpand(f); },
        // The Primary row's destructive control is the SAME control a registry row has - same label
        // (`remove`), same two clicks - and what it takes away is still the Primary SLOT: the host's
        // endpoint_clear {fn} is that verb, and it is sent here (clearPrimary), not in the shared row component.
        onRemoveArm: function (v) { setClearArmed(!!v); },
        onRemoveRun: function (f) { setClearArmed(false); if (props.onClear) props.onClear(f); },
        onAction: props.onAction,
        onModels: function (f) { if (props.onModels) props.onModels(f); },
        // The primary row's own re-probe. The id the host's health verb expects for it is "primary".
        // The third argument is the merged read's quiet flag, passed through to probeOneEndpoint.
        onProbe: function (f, id, quiet) { if (props.onProbe) props.onProbe(f, id, quiet); },
        modelsTitle: (hostAnswer
          ? ("The model half of that read refreshes the model dropdown AND stamps this primary's own cached capability answer, and that answer survives a restart.")
          : ("The model half of that read refreshes the model dropdown. This host does not report a cached answer for the primary, so this row shows the dropdown catalog and says so on the row.")),
        modelsUnknownTip: (hostAnswer
          ? "no capability answer for this primary yet: it has never been read this session or since the last restart. Press read now to read it off the engine."
          : "no capability answer yet: press read now to read it off this endpoint."),
